def volt_laplacian(m, edges):
    L = matrix(Lzw, m, m)
    for (u, v, (a, b)) in edges:
        mon = zL**a * wL**b
        if u == v:
            L[u, u] += _sage_const_2  - mon - mon**(-_sage_const_1 )
        else:
            L[u, u] += _sage_const_1 ; L[v, v] += _sage_const_1 
            L[u, v] -= mon; L[v, u] -= mon**(-_sage_const_1 )
    return L

def detL(m, edges):
    return volt_laplacian(m, edges).det()

def derived_edges(m, edges, N, Np):
    out = []
    for (u, v, (a, b)) in edges:
        for i in range(N):
            for j in range(Np):
                x = (i * Np + j) * m + u
                y = (((i + a) % N) * Np + ((j + b) % Np)) * m + v
                out.append((x, y))
    return out

def int_laplacian(nv, uedges):
    Lap = matrix(ZZ, nv, nv)
    for (x, y) in uedges:
        if x == y:
            continue
        Lap[x, x] += _sage_const_1 ; Lap[y, y] += _sage_const_1 
        Lap[x, y] -= _sage_const_1 ; Lap[y, x] -= _sage_const_1 
    return Lap

def kappa_derived(m, edges, N, Np):
    nv = m * N * Np
    Lap = int_laplacian(nv, derived_edges(m, edges, N, Np))
    return Lap.delete_rows([_sage_const_0 ]).delete_columns([_sage_const_0 ]).det()

def n_components(nv, uedges):
    parent = list(range(nv))
    def find(a):
        while parent[a] != a:
            parent[a] = parent[parent[a]]; a = parent[a]
        return a
    for (x, y) in uedges:
        rx, ry = find(x), find(y)
        if rx != ry:
            parent[rx] = ry
    return len(set(find(a) for a in range(nv)))

def base_connected(m, edges):
    return n_components(m, [(u, v) for (u, v, _) in edges]) == _sage_const_1 

def cycle_voltage_lattice(m, edges):
    parent = list(range(m))
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]; x = parent[x]
        return x
    tree, nontree = [], []
    for e in edges:
        (u, v, a) = e
        if u == v:
            nontree.append(e); continue
        ru, rv = find(u), find(v)
        if ru != rv:
            parent[ru] = rv; tree.append(e)
        else:
            nontree.append(e)
    h = {_sage_const_0 : vector(ZZ, [_sage_const_0 , _sage_const_0 ])}
    adj = {}
    for (u, v, a) in tree:
        adj.setdefault(u, []).append((v, vector(ZZ, a)))
        adj.setdefault(v, []).append((u, -vector(ZZ, a)))
    stack = [_sage_const_0 ]
    while stack:
        x = stack.pop()
        for (y, a) in adj.get(x, []):
            if y not in h:
                h[y] = h[x] + a; stack.append(y)
    gens = []
    for (u, v, a) in nontree:
        gens.append(vector(ZZ, a) + h[u] - h[v])
    return gens

def connected_by_lattice(m, edges, N, Np):
    if not base_connected(m, edges):
        return False
    gens = cycle_voltage_lattice(m, edges)
    rows = [list(g) for g in gens] + [[N, _sage_const_0 ], [_sage_const_0 , Np]]
    M = matrix(ZZ, rows)
    if M.nrows() == _sage_const_0 :
        return N == _sage_const_1  and Np == _sage_const_1 
    d = [x for x in M.elementary_divisors() if x != _sage_const_0 ]
    return len(d) == _sage_const_2  and d[_sage_const_0 ] == _sage_const_1  and d[_sage_const_1 ] == _sage_const_1 

def content_of(F):
    cs = [ZZ(c) for c in F.coefficients()]
    if not cs:
        return ZZ(_sage_const_0 )
    return gcd(cs)

def clear_monomial(D):
    if D == _sage_const_0 :
        return (_sage_const_0 , _sage_const_0 , Rzw(_sage_const_0 ))
    ex = [e for e in D.dict().keys()]
    r = min(e[_sage_const_0 ] for e in ex); s = min(e[_sage_const_1 ] for e in ex)
    P = Rzw({(e[_sage_const_0 ] - r, e[_sage_const_1 ] - s): ZZ(c) for (e, c) in D.dict().items()})
    return (r, s, P)

def f_series(D):
    (r, s, P) = clear_monomial(D)
    return RTS(P.subs({zg: _sage_const_1  + Tg, wg: _sage_const_1  + Sg}))

def mu_content(D, ell):
    return ZZ(content_of(D)).valuation(ell)

def lowest_form(D, ell):
    """f = P(1+T,1+S) の mod ell 還元の最低次斉次部分 H とその次数 k。"""
    f = f_series(D)
    Fl = GF(ell)
    fb = f.change_ring(Fl)
    if fb == _sage_const_0 :
        return (None, None)
    k = min(e[_sage_const_0 ] + e[_sage_const_1 ] for (e, c) in fb.dict().items() if c != _sage_const_0 )
    RTSl = PolynomialRing(Fl, ['T', 'S'])
    H = RTSl({e: c for (e, c) in fb.dict().items() if e[_sage_const_0 ] + e[_sage_const_1 ] == k and c != _sage_const_0 })
    return (k, H)

def rational_zeros(H, ell):
    """H の P^1(F_ell) 上の有理零点（'(0:1)' と '(1:c)' の list）。"""
    Tl, Sl = H.parent().gens()
    out = []
    if H.subs({Tl: _sage_const_0 , Sl: _sage_const_1 }) == _sage_const_0 :
        out.append('(0:1)')
    for c in GF(ell):
        if H.subs({Tl: _sage_const_1 , Sl: c}) == _sage_const_0 :
            out.append('(1:%s)' % c)
    return out

def J0_of(ell, k):
    J = _sage_const_1 
    while euler_phi(ell**J) <= k:
        J += _sage_const_1 
    return J

