def prod_nontrivial_resultant(D, N, Np):
    if N == _sage_const_1  and Np == _sage_const_1 :
        return ZZ(_sage_const_1 )
    (r, s, P) = clear_monomial(D)
    if P == _sage_const_0 :
        return ZZ(_sage_const_0 )
    if N == _sage_const_1 :
        part1 = ZZ(_sage_const_1 )
    else:
        A = Rz((wP**Np - _sage_const_1 ).resultant(RzW(P)))
        if A == _sage_const_0 :
            return ZZ(_sage_const_0 )
        Q = Rz((zp**N - _sage_const_1 ) // (zp - _sage_const_1 ))
        u1 = ZZ((-_sage_const_1 )**(N + _sage_const_1 ))**(r * Np)
        u2 = ZZ((-_sage_const_1 )**(Np + _sage_const_1 ))**(s * (N - _sage_const_1 ))
        part1 = u1 * u2 * ZZ(Q.resultant(A))
    if Np == _sage_const_1 :
        part2 = ZZ(_sage_const_1 )
    else:
        P1 = Rz(P.subs({zg: ZZ(_sage_const_1 ), wg: zp}))
        if P1 == _sage_const_0 :
            return ZZ(_sage_const_0 )
        Qp = Rz((zp**Np - _sage_const_1 ) // (zp - _sage_const_1 ))
        part2 = ZZ((-_sage_const_1 )**(Np + _sage_const_1 ))**s * ZZ(Qp.resultant(P1))
    return part1 * part2

_TOWER_CACHE = {}

# 1 段あたりの計算時間の上限（秒）。終結式の次数は ell^{2n} で増えるので、
# 深い段は現実的な時間で終わらない。打ち切った段は 'TO' として記録し、
# SKIPS に残して実行末尾で一覧を出す（黙って範囲を狭めないため）。
STAGE_BUDGET = _sage_const_420 
SKIPS = []

def tower_ords(m, edges, ell, nmax, tag='', budget=None):
    """ord_ell(kappa_n) の list（n = 0..nmax）。
       塔が非連結な段は None、時間上限で打ち切った段は 'TO'。
       budget を渡すとその段あたり秒数を使う（既定は STAGE_BUDGET）。"""
    if budget is None:
        budget = STAGE_BUDGET
    key = (m, tuple(sorted((u, v, a, b) for (u, v, (a, b)) in edges)), ell, nmax)
    if key in _TOWER_CACHE:
        return _TOWER_CACHE[key]
    D = detL(m, edges)
    k0 = kappa_derived(m, edges, _sage_const_1 , _sage_const_1 )
    out = []
    for n in range(nmax + _sage_const_1 ):
        N = ell**n
        if not connected_by_lattice(m, edges, N, N):
            out.append(None); continue
        try:
            alarm(budget)
            pr = prod_nontrivial_resultant(D, N, N)
            cancel_alarm()
        except AlarmInterrupt:
            cancel_alarm()
            SKIPS.append((tag, m, tuple((u, v, a, b) for (u, v, (a, b)) in edges),
                          ell, n, budget))
            out.append('TO')
            # 以降の段はさらに重いので打ち切る
            for _ in range(n + _sage_const_1 , nmax + _sage_const_1 ):
                out.append('TO')
            break
        if pr == _sage_const_0 :
            out.append(None); continue
        out.append(ZZ(ZZ(k0 * pr)).valuation(ell) - _sage_const_2  * n)
    _TOWER_CACHE[key] = out
    return out


def usable_prefix(ords):
    """先頭から連続する「実際に計算できた段」だけを返す（None / 'TO' で打ち切り）。"""
    out = []
    for o in ords:
        if o is None or o == 'TO':
            break
        out.append(o)
    return out

